import 'package:win32_clipboard/win32_clipboard.dart';

void main() async {
  Clipboard.setText('Hello, clipboard!');
  final text = Clipboard.getText();
  print(text);

  final monitor = ClipboardChangeMonitor();
  await monitor.start();
  monitor.events.listen((_) => print('Clipboard changed'));
  // ...
  await monitor.close();
}
